import { ROLE_TEMPLATES, type RoleTemplateKey } from "@fnb/domain";
import type pg from "pg";
import { newId } from "../ids/new-id";
import { withTenant } from "../tenancy/with-tenant";
import { encodeRoleGrants } from "./role-grants-codec";

export interface OrganizationToProvision {
  /** Generated by the caller when it must know the id first; a new one otherwise. */
  organizationId?: string;
  name: string;
  /** The global account signing up. It becomes the first member, holding the owner role. */
  creator: { accountId: string; displayName: string };
  /** The API's clock, the only clock: every row is stamped with it. */
  now: Date;
}

export interface ProvisionedOrganization {
  tenantId: string;
  appUserId: string;
  membershipId: string;
  roleIds: Readonly<Record<RoleTemplateKey, string>>;
}

// Starting names only. From the first save on they are the shop's own data, renamed and
// edited at will, which is why they are written into the rows instead of looked up.
const TEMPLATE_ROLE_NAMES: Readonly<Record<RoleTemplateKey, string>> = {
  owner: "Chủ quán",
  manager: "Quản lý ca",
  cashier: "Thu ngân",
  waiter: "Phục vụ",
  barista: "Pha chế",
  stock_keeper: "Thủ kho",
};

const TEMPLATE_KEYS = Object.keys(ROLE_TEMPLATES) as RoleTemplateKey[];

/**
 * A new organization with the six template roles and its creator as owner, in one
 * transaction: an organization nobody can administer, or a member without a role, never
 * exists even for a moment. The account must already exist in fnb_auth.
 */
export async function provisionOrganization(
  pool: pg.Pool,
  input: OrganizationToProvision,
): Promise<ProvisionedOrganization> {
  const tenantId = input.organizationId ?? newId();
  const appUserId = newId();
  const membershipId = newId();
  const roleIds = Object.fromEntries(TEMPLATE_KEYS.map((key) => [key, newId()])) as Record<
    RoleTemplateKey,
    string
  >;
  const { now } = input;
  await withTenant(pool, tenantId, async (client) => {
    await client.query(
      "INSERT INTO organization (id, tenant_id, name, created_at, updated_at, created_by) " +
        "VALUES ($1, $1, $2, $3, $3, $4)",
      [tenantId, input.name, now, appUserId],
    );
    await client.query(
      "INSERT INTO app_user (id, tenant_id, display_name, created_at, updated_at, created_by) " +
        "VALUES ($1, $2, $3, $4, $4, $1)",
      [appUserId, tenantId, input.creator.displayName, now],
    );
    for (const key of TEMPLATE_KEYS) {
      const stored = encodeRoleGrants(ROLE_TEMPLATES[key].grants);
      await client.query(
        "INSERT INTO role (id, tenant_id, name, permission_keys, thresholds, is_template, " +
          "created_at, updated_at, created_by) VALUES ($1, $2, $3, $4, $5, true, $6, $6, $7)",
        [
          roleIds[key],
          tenantId,
          TEMPLATE_ROLE_NAMES[key],
          stored.permissionKeys,
          stored.thresholds,
          now,
          appUserId,
        ],
      );
    }
    await client.query(
      "INSERT INTO membership (id, tenant_id, account_id, app_user_id, role_id, created_at, " +
        "updated_at, created_by) VALUES ($1, $2, $3, $4, $5, $6, $6, $4)",
      [membershipId, tenantId, input.creator.accountId, appUserId, roleIds.owner, now],
    );
  });
  return { tenantId, appUserId, membershipId, roleIds };
}
